def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    colored=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,3)]
    blank=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]==0 and grid[r-1][c]==grid[r+1][c]==grid[r][c-1]==grid[r][c+1]==3:
                blank.append((r,c))
    def cast(r,c,dr,dc,color):
        i,j=r+dr,c+dc
        # Cross's own arm is preserved and the ray continues beyond it.
        if 0<=i<h and 0<=j<w and grid[i][j]==3:
            i+=dr; j+=dc
        while 0<=i<h and 0<=j<w and grid[i][j]==0:
            out[i][j]=color
            i+=dr; j+=dc
    # Horizontal first, then vertical so vertical rays win at crossings.
    for r,c,v in colored:
        cast(r,c,0,-1,v); cast(r,c,0,1,v)
    for r,c,v in colored:
        cast(r,c,-1,0,v); cast(r,c,1,0,v)
    # Uncolored crosses leave their complete axes untouched/blank.
    for r,c in blank:
        for j in range(w):
            if grid[r][j]==0: out[r][j]=0
        for i in range(h):
            if grid[i][c]==0: out[i][c]=0
    return out
