def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    # Colored crosses extend their color through their complete row and column.
    for r, c, color in centers:
        for j in range(w):
            if grid[r][j] == 0:
                out[r][j] = color
    for r, c, color in centers:
        for i in range(h):
            if grid[i][c] == 0:
                out[i][c] = color
    # Crosses whose center is blank designate empty full rows and columns.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r-1][c] == 3 and grid[r+1][c] == 3
                    and grid[r][c-1] == 3 and grid[r][c+1] == 3):
                for j in range(w):
                    if grid[r][j] == 0:
                        out[r][j] = 0
                for i in range(h):
                    if grid[i][c] == 0:
                        out[i][c] = 0
    return out
